    theme: string;
    custom: string;
    menu: string;
    borderOpacity: string;
    surfaceStyle: string;
    cssVars: string;
    reset: string;
  };
  /** Variant group labels (surfaces / hairlines / …). */
  groups: {
    surfaces: string;
    fills: string;
    hairlines: string;
    brand: string;
    sidebar: string;
    feedback: string;
    charts: string;
  };
  /** Variant token labels (background / card / primary / …). */
