    background: string;
    card: string;
    popover: string;
    carbon: string;
    mask: string;
    foreground: string;
    mutedForeground: string;
    cardForeground: string;
    popoverForeground: string;
    carbonForeground: string;
    muted: string;
    accent: string;
    accentForeground: string;
    secondary: string;
    secondaryForeground: string;
    border: string;
    input: string;
    ring: string;
    primary: string;
    primaryForeground: string;
    sidebar: string;
    sidebarForeground: string;
    sidebarBorder: string;
    sidebarAccent: string;
    sidebarAccentForeground: string;
    sidebarPrimary: string;
    sidebarPrimaryForeground: string;
    sidebarRing: string;
    destructive: string;
    destructiveForeground: string;
    success: string;
    successForeground: string;
    warning: string;
    warningForeground: string;
    info: string;
    infoForeground: string;
    chart1: string;
    chart2: string;
    chart3: string;
    chart4: string;
    chart5: string;
  };
  /** Select option labels (feedback scheme and menu settings). */
  options: {
    mode: {
      auto: string;
      light: string;
      dark: string;
    };
    size: {
      xs: string;
      sm: string;
      md: string;
      lg: string;
      xl: string;
      xl2: string;
    };
    spacing: {
      compact: string;
      default: string;
      relaxed: string;
      spacious: string;
    };
    /**
     * Font family labels, keyed by family (not by role).
     *
     * The four font roles (`sans` / `heading` / `mono` / `serif`) all draw from
     * this one catalog — a heading may be any family, and the same family is
     * spelled the same wherever it appears — so a family is labelled once
     * instead of once per role.
     */
    fontFamilies: {
      system: string;
      geist: string;
      inter: string;
      notoSans: string;
      nunitoSans: string;
      figtree: string;
      roboto: string;
      raleway: string;
      dmSans: string;
      publicSans: string;
      outfit: string;
      oxanium: string;
      manrope: string;
      spaceGrotesk: string;
      montserrat: string;
      ibmPlexSans: string;
      sourceSans3: string;
      instrumentSans: string;
      jetbrainsMono: string;
      geistMono: string;
      notoSerif: string;
      robotoSlab: string;
      merriweather: string;
      lora: string;
      playfairDisplay: string;
      ebGaramond: string;
      instrumentSerif: string;
    };
    feedback: {
      classic: string;
      vivid: string;
      subtle: string;
      modern: string;
      professional: string;
    };
    sidebar: {
      derived: string;
      invertedDark: string;
      soft: string;
      contrast: string;
    };
    surfaceStyle: {
      layered: string;
      flat: string;
    };
  };
  /** Labels used by the `PalettePicker` component. */
  palettePicker: {
    /** Label for the custom color option. */
    custom: string;
    /** Label for the recommended palette switch. */
    recommendedPalette: string;
  };
}

