/**
 * Resolve the shared theme locale messages for the current UI locale.
 *
 * Chinese (`zh`-prefixed) locales use the `zh` labels; every other locale
 * (including the default `en`) falls back to English.
 */
export function useThemeLocale(): ComputedRef<ThemeLocaleMessages> {
  const config = inject<ConfigProviderContext>(UI_CONFIG_PROVIDER_CONTEXT_KEY);

  return computed(() => {
    const locale = config?.locale ?? 'en';

    return locale.startsWith('zh') ? themeLocaleZh : themeLocaleEn;
  });
}

import { computed } from 'vue';
import { useThemeLocale } from './locale';

export type OptionCategory = 'mode' | 'size' | 'spacing' | 'fontFamilies' | 'feedback' | 'sidebar' | 'surfaceStyle';

/** 把 kebab-case 选项值（如 `inverted-dark` / `noto-sans`）转换为消息对象里的 camelCase 键（`invertedDark`）。 */
const kebabToCamel = (key: string): string => key.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());

/** 消息键：kebab → camel；`2xl` 尺寸值映射为 `xl2` 键。 */
const toMessageKey = (category: OptionCategory, value: string): string => {
  if (category === 'size') {
    return value === '2xl' ? 'xl2' : value;
  }

  if (value === 'system') {
    return 'system';
  }

  return kebabToCamel(value);
};

/**
 * ThemeCustomizer 文案解析：跟随 ConfigProvider.locale 响应式刷新（仅 zh/en）。
 * `resolveLabel` 解析 sections / groups / variants，`resolveOption` 解析各下拉选项标签。
 */
export function useThemeCustomizerLocale() {
  const messages = useThemeLocale();
  const tc = computed(() => messages.value);

  const resolveLabel = (key: string): string => {
    const m = tc.value;

    if (key.startsWith('theme.group.')) {
      return m.groups[key.slice('theme.group.'.length) as keyof typeof m.groups] ?? key;
    }

    if (key.startsWith('theme.variant.')) {
      return m.variants[key.slice('theme.variant.'.length) as keyof typeof m.variants] ?? key;
    }

    return m.sections[key as keyof typeof m.sections] ?? key;
  };

  const resolveOption = (category: OptionCategory, key: string): string => {
    const map = tc.value.options[category] as Record<string, string>;

    return map[toMessageKey(category, key)] ?? key;
  };

  return { tc, resolveLabel, resolveOption };
}

import type { ClassValue, UiClass } from '@vean/aria/types';
import type { ThemeSize } from '@/theme';

/**
 * the selectable sections of the theme customizer.
 */
export type ThemeCustomizerSection =
  | 'mode'
  | 'palette'
  | 'radius'
  | 'size'
  | 'spacing'
  | 'font'
  | 'scheme'
  | 'advanced';

/**
 * the control surface of the theme customizer shell.
 *
 * `root` is the outer box (the fixed width / height lives there, so a host can
 * resize it through `ui.root`); `tabs` / `content` drive the panel scroller and
 * `panel` / `actions` are the inner regions.
 */
export type ThemeCustomizerUiSlot = 'root' | 'tabs' | 'content' | 'panel' | 'actions';

/**
 * the slot-class map of the theme customizer shell.
 */
export type ThemeCustomizerUi = UiClass<ThemeCustomizerUiSlot>;

/**
 * Properties for the ThemeCustomizer component.
 *
 * A real-app reusable theme settings body. It does not own any container
 * (popover / drawer / sidebar) — the caller hosts it and decides the shell.
 */
export interface ThemeCustomizerProps {
  /**
   * Additional class names applied to the root element.
   */
  class?: ClassValue;
  /**
   * Per-slot class overrides for the component shell.
   *
   * `ui.root` carries the outer box, so a host can drop the default fixed width
   * / height (`w-96 h-[70vh]`) when it already constrains the surface itself.
   */
  ui?: Partial<ThemeCustomizerUi>;
  /**
   * The sections to show (defaults to all).
   */
  sections?: ThemeCustomizerSection[];
  /**
   * The size forwarded to the underlying controls.
   */
  size?: ThemeSize;
  /**
   * Whether to persist changes to storage.
   *
   * @default true
   */
  persist?: boolean;
  /**
   * Whether to show the bottom action row (save preset / reset).
   *
   * @default true
   */
  showActions?: boolean;
  /**
   * Resolve a label key (section / group / variant token) to a display string.
   */
  labelResolver?: (key: string) => string;
}

// @unocss-include
import { scv } from '@soybeanjs/cva';

/**
 * the theme customizer shell.
 *
 * The panel owns a **stable box**: a fixed width plus a fixed height whose
 * content region scrolls, and `scrollbar-gutter: stable` reserves the scrollbar
 * track in both directions. Without that, switching between the Theme and Custom
 * panels resized the host popover on every tab change (the scrollbar appeared
 * and the content was taller or shorter).
 * `ui.root` is the escape hatch for a host that wants a different box.
 *
 * The viewport cap keeps the fixed width from overflowing a phone-sized popover;
 * a host that already constrains the surface drops it along with the width by
 * overriding `ui.root`.
 */
export const themeCustomizerVariants = scv({
  slots: {
    root: 'flex flex-col gap-3 w-96 max-w-[calc(100vw-2rem)] max-h-fit h-[70vh]',
    tabs: 'grow min-h-0',
    content: 'min-h-0 overflow-auto [scrollbar-gutter:stable]',
    panel: 'space-y-4 p-2',
    actions: 'shrink-0 space-y-3 border-t pt-4'
  }
});

import { computed, ref } from 'vue';
import type { ComputedRef, Ref } from 'vue';
import { DEFAULT_OPTIONS } from '@vean/theme';
import type { ThemeModePreference, ThemeOptions, ThemeOverrides } from '@vean/theme';
import { readThemeEnvelope, writeThemeEnvelope, THEME_STORAGE_KEY } from '@vean/theme/storage';

/** the editable theme settings state: engine options plus the mode preference. */
export type ThemeSettingsState = ThemeOptions & { mode?: ThemeModePreference };

/**
 * Options for `useThemeSettings`.
 */
export interface UseThemeSettingsOptions {
  /**
   * The initial configuration. When omitted and `persist` is enabled, the
   * persisted envelope is read from storage.
   */
  initial?: ThemeSettingsState;
  /**
   * Whether to read/write the persisted theme envelope from storage.
   *
   * Off by default: inside an `SConfigProvider` tree the provider owns the
   * single envelope writer, and `apply` hands the state to the runtime. Enable
   * it only for standalone usage without a provider.
   *
   * @default false
   */
  persist?: boolean;
  /**
   * The localStorage key backing the persisted envelope.
   *
   * @default THEME_STORAGE_KEY
   */
  storageKey?: string;
  /**
   * The callback invoked by `commit()` to apply the config to the runtime
   * (e.g. `useTheme().setThemeState`).
   */
  apply?: (state: ThemeSettingsState) => void;
}

/**
 * The return value of `useThemeSettings`.
 */
export interface UseThemeSettingsReturn {
  /** The complete writable config (engine options + mode preference). */
  state: Ref<ThemeSettingsState>;
  /** Immutably patch the config (single field or object). */
  setState: (patch: Partial<ThemeSettingsState>) => void;
  /** The editable light/dark single-token overrides. */
  overrides: ComputedRef<ThemeOverrides>;
  /**
   * Set or clear a single override token. Empty values are removed.
   *
   * The key is a token name owned by the engine (`SemanticToken`); it stays a
   * plain `string` here so the settings layer does not encode the vocabulary,
   * and the persisted payload is validated field by field anyway.
   */
  setOverride: (mode: 'light' | 'dark', key: string, value: string) => void;
  /** The engine options derived from `state` (mode stripped), ready for the engine. */
  resolved: ComputedRef<ThemeOptions>;
  /** Persist the config (when `persist`) and call `apply` to push it to the runtime. */
  commit: () => void;
  /** Reset to the engine defaults and clear overrides. */
  reset: () => void;
}

const hasAnyOverride = (overrides: ThemeOverrides | undefined): boolean =>
  overrides != null && (Object.keys(overrides.light ?? {}).length > 0 || Object.keys(overrides.dark ?? {}).length > 0);

/**
 * The UI-layer theme configuration state core.
 *
 * Owns the editable settings state (base/primary/feedback/levels/surface
 * style/size/radius/spacing/overrides/mode), immutable `setState`/`setOverride`
 * updates, and the engine options derived from the state. Used by the theme
 * customizer; pure logic and storage, no component rendering.
 */
export function useThemeSettings(options: UseThemeSettingsOptions = {}): UseThemeSettingsReturn {
  const { initial, persist = false, storageKey = THEME_STORAGE_KEY, apply } = options;

  const persisted = persist && !initial ? readThemeEnvelope(storageKey) : null;
  const state = ref<ThemeSettingsState>({
    ...(persisted ? { ...persisted.options, ...(persisted.mode ? { mode: persisted.mode } : {}) } : undefined),
    ...initial
  });

  const setState = (patch: Partial<ThemeSettingsState>): void => {
    state.value = { ...state.value, ...patch };
  };

  const overrides = computed<ThemeOverrides>(
    () =>
      state.value.overrides ?? {
        light: {},
        dark: {}
      }
  );

  /**
   * set or clear one override value.
   *
   * The value stays a plain `string`: this layer deliberately does not encode the
   * `TokenOverride` vocabulary (`stone.950` / `oklch(...)` / `white` / `token.primary` …),
   * because the values come from pickers and inputs, and the engine's own parser
   * decides what a value means. The write therefore asserts into the narrower
   * `ThemeOverrides` — validation lives in `parseOverrides`, not here.
   */
  const setOverride = (mode: 'light' | 'dark', key: string, value: string): void => {
    const current: ThemeOverrides = state.value.overrides ?? {
      light: {},
      dark: {}
    };
    const modeTokens = { ...current[mode] } as Record<string, string>;

    if (value === '') {
      // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
      delete modeTokens[key];
    } else {
      modeTokens[key] = value;
    }

    const next = { ...current, [mode]: modeTokens } as ThemeOverrides;

    if (!hasAnyOverride(next)) {
      setState({ overrides: undefined });
      return;
    }

    setState({ overrides: next });
  };

  const resolved = computed<ThemeOptions>(() => {
    const { mode: _mode, ...rest } = state.value;

    return rest;
  });

  const commit = (): void => {
    if (persist) {
      // read-modify-write: standalone usage must not drop the style snapshot or
      // the presets the provider may have written into the same envelope
      const envelope = readThemeEnvelope(storageKey);

      writeThemeEnvelope({ ...envelope, options: resolved.value, mode: state.value.mode }, storageKey);
    }

    apply?.(state.value);
  };

  const reset = (): void => {
    state.value = {
      base: DEFAULT_OPTIONS.base,
      primary: DEFAULT_OPTIONS.primary,
      feedback: DEFAULT_OPTIONS.feedback,
      surfaceStyle: DEFAULT_OPTIONS.surfaceStyle,
      size: DEFAULT_OPTIONS.size,
      radius: DEFAULT_OPTIONS.radius,
      spacing: DEFAULT_OPTIONS.spacing,
      // 字体回到引擎默认系统栈（LITERAL_DEFAULTS）
      font: undefined,
      borderOpacity: DEFAULT_OPTIONS.borderOpacity,
      format: DEFAULT_OPTIONS.format,
      mode: 'light',
      overrides: undefined
    };
  };

  return {
    state,
    setState,
    overrides,
    setOverride,
    resolved,
    commit,
    reset
  };
}

import { computed } from 'vue';
import type { ComputedRef, Ref, WritableComputedRef } from 'vue';
import { resolveThemeMap, valueRef } from '@vean/theme';
import type { ColorValue, SemanticToken, TokenValue } from '@vean/theme';
import type { UseThemeSettingsReturn } from './use-theme-settings';

/**
 * the variant group keys a token can belong to.
 */
export type VariantGroupKey = 'surfaces' | 'fills' | 'hairlines' | 'brand' | 'sidebar' | 'feedback' | 'charts';

/**
 * the metadata of a single variant token.
 */
export interface VariantTokenMeta {
  /** the color token key. */
  key: SemanticToken;
  /** the group this token belongs to. */
  group: VariantGroupKey;
  /** the derivation source: base / primary / scheme. */
  source: 'base' | 'primary' | 'scheme';
  /** whether the token follows the background-shade (light/dark level) offset. */
  shadeLinked?: boolean;
  /** a label key used for display (falls back to the token key itself). */
  i18n: string;
}

/**
 * a variant group: its label and the tokens it contains.
 */
export interface VariantGroupMeta {
  /** the group key. */
  key: VariantGroupKey;
  /** the group label key. */
  i18n: string;
  /** the tokens in this group. */
  tokens: VariantTokenMeta[];
}

/**
 * Options for `useThemeVariants`.
 */
export interface UseThemeVariantsOptions {
  /** the settings state core exposing `state` / `setOverride` / `resolved`. */
  settings: UseThemeSettingsReturn;
  /** the active light/dark mode used to select the derived tokens. */
  mode: Ref<'light' | 'dark'>;
  /** optional custom group list; defaults to the built-in variant groups. */
  groups?: VariantGroupMeta[];
}

/**
 * The return value of `useThemeVariants`.
 */
export interface UseThemeVariantsReturn {
  /** the variant groups (group → tokens). */
  groups: VariantGroupMeta[];
  /** the derived tokens from the left-column generator (the resolved preset). */
  derived: ComputedRef<Record<SemanticToken, string>>;
  /** a writable ref bound to the override for a token key. */
  getOverride: (key: SemanticToken) => WritableComputedRef<string>;
  /** merge rule: override wins when present, otherwise falls back to derived (`token.*` refs resolve to a colour form for the picker). */
  final: ComputedRef<Record<SemanticToken, ColorValue>>;
  /** whether the active mode has any explicit override. */
  hasOverrides: ComputedRef<boolean>;
  /** clear the override for a token key. */
  clearOverride: (key: SemanticToken) => void;
}

