/**
 * the built-in variant groups.
 */
export const DEFAULT_VARIANT_GROUPS: VariantGroupMeta[] = [
  { key: 'surfaces', i18n: 'theme.group.surfaces', tokens: [...surfaces, ...mask] },
  { key: 'fills', i18n: 'theme.group.fills', tokens: fills },
